import React from 'react'
import { useSelector } from "react-redux";
function TaskStatus() {
     const tasks = useSelector((state) => state.tasks);
  const completedCount = tasks.filter((task) => !task.inProgress).length;
  const pendingCount = tasks.filter((task) => task.inProgress).length;
  return (
    <div>
      <div className="status">
        <div className="completeStatus">
          <h2>COMPLETED TASKS</h2>
          <p>{completedCount}</p>
        </div>

        <div pendingStatus>
          <h2>Pending TASKS</h2>
          <p>{pendingCount}</p>
        </div>
      </div>
    </div>
  )
}
export default TaskStatus
